data.query:
query Query($whereShipment: ShipmentWhereInput, $product: ProductWhereInput, $customer: CustomerWhereInput, $unit: UnitWhereInput, $facility: FacilityWhereInput, $location: LocationWhereInput) {
  shipment(where: $whereShipment) {
    total
    edges {
      node {
        id
        number
        shipmentStageId
        shipmentLines {
          edges {
            node {
              id
            }
          }
        }
      }
    }
  }
  product(where: $product) {
    edges {
      node {
        id
        externalId
        productTypeId
        strategies {
          edges {
            node {
              id
              strategyProcesses(where: {final: {_eq: true}}) {
                edges {
                  node {
                    id
                  }
                }
              }
            }
          }
        }
      }
    }
  }
  customer(where: $customer) {
    edges {
      node {
        id
        externalId
      }
    }
  }
  unit(where: $unit) {
    edges {
      node {
        id
      }
    }
  }
  location(where: $location) {
    edges {
      node {
        id
        name
        facility {
          externalId
        }
      }
    }
  }
  facility(where: $facility) {
    edges {
      node {
        id
        externalId
      }
    }
  }
}

