data.mutation:
mutation ($payloadLoad: [LoadCreatePayloadInput!]!,
  $payloadShipment: [ShipmentCreatePayloadInput!]!,
  $payloadShipmentLine: [ShipmentLineCreatePayloadInput!]!) {
  createLoad(payload: $payloadLoad) {
    id
    number
  }
  createShipment(payload: $payloadShipment) {
    id
    shipmentStageId
  }
  createShipmentLine(payload: $payloadShipmentLine) {
    id
    shipmentLineStageId
  }
}

